/* UNDR.RATED.SZN — independent design prototype, not a connected Shopify theme.
   Product data is a public-site snapshot from 2026-10-14. No payments or form data are sent.
   Only anonymous preview-bag selections are stored locally. */
'use strict';
const D=window.UNDR_DATA;
const A=Object.fromEntries(D.assets.map(a=>[a.id,a]));
const P=Object.fromEntries(D.products.map(p=>[p.id,p]));
const app=document.getElementById('app');
const modal=document.getElementById('dialog');
const storageKey='undrszn-design-preview-bag-v1';
let cart=loadCart(), shopFilter='all', imageMode='worn', archiveFilter='all', selectedSizes={}, galleryIndexes={};
let activePath='/', scrollMemory={}, lastFocus=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const href=path=>'#'+path;
const total=()=>cart.reduce((n,l)=>n+P[l.product].price*l.qty,0);
const count=()=>cart.reduce((n,l)=>n+l.qty,0);
function loadCart(){try{const v=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(v)?v.filter(l=>D.products.some(p=>p.id===l.product&&p.sizes.includes(l.size))&&Number.isInteger(l.qty)&&l.qty>0&&l.qty<=9):[];}catch{return [];}}
function saveCart(){try{localStorage.setItem(storageKey,JSON.stringify(cart));}catch{toast('Browser storage is unavailable. Your preview bag will last for this visit only.');}document.querySelectorAll('[data-bag-count]').forEach(e=>e.textContent=count());}
function icon(name){const shapes={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',menu:'<path d="M3 8h18M3 16h18"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${shapes[name]||''}</svg>`;}
function sourceURL(a,width=1200){if(D.media_mode==='local')return a.local_file;let u=a.original_url;if(a.id==='film-car'||a.id==='film-arrival')return u;return u.replace(/([?&])width=\d+/,`$1width=${width}`);}
function media(id,cls='',eager=false){const a=A[id];if(!a)return '';const src=sourceURL(a);const responsive=D.media_mode!=='local'&&!['film-car','film-arrival'].includes(id)?`srcset="${esc(sourceURL(a,480))} 480w, ${esc(sourceURL(a,800))} 800w, ${esc(sourceURL(a,1200))} 1200w" sizes="(max-width:760px) 85vw, 55vw"`:'';return `<div class="media ${cls}" data-media-id="${id}"><img src="${esc(src)}" ${responsive} width="800" height="1000" alt="${esc(a.alt)}" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''} decoding="async"></div>`;}
function price(p){return `<div class="prices">${money(p.price)}${p.compare_at?` <del>${money(p.compare_at)}</del>`:''}</div>`;}
function header(){return `<div class="announcement">UNDR.RATED.SZN &nbsp; — &nbsp; DIRTY RODMAN COLLECTION</div><header class="header"><nav class="nav" aria-label="Main navigation"><a href="${href('/collections/all')}" class="${activePath.includes('collections')?'active':''}">Shop</a><a href="${href('/pages/behind-the-scenes-dirty-rodman')}">The campaign</a><a href="${href('/pages/about-undr-rated-szn')}">Our story</a></nav><button class="icon-button mobile-toggle" data-action="menu" aria-label="Open menu">${icon('menu')}</button><a class="wordmark" href="${href('/')}" aria-label="UNDR.RATED.SZN home">UNDR.<span>RATED<br>SZN</span></a><div class="header-actions"><a class="mobile-shop" href="${href('/collections/all')}">Shop</a><a class="icon-button" href="${href('/search')}" aria-label="Search the collection">${icon('search')}</a><a class="icon-button account-link" href="${href('/account')}" aria-label="Your account">${icon('user')}</a><button class="bag-button" data-action="bag" aria-label="Open preview bag">${icon('bag')}<span>(<span data-bag-count>${count()}</span>)</span></button></div></header>`;}
function footer(){return `<footer class="footer"><div class="footer-top"><div class="footer-intro"><span class="eyebrow">UNDR.RATED.SZN</span><p class="footer-lead">Uncomfortable Nights<br>Develop Resilience.</p></div><div><h3>The collection</h3><a href="${href('/collections/all')}">Shop all</a><a href="${href('/products/dirty-rodman-hoodie')}">Dirty Rodman / Black</a><a href="${href('/products/deluxe-dirty-rodamn')}">Dirty Rodman / Cream</a><a href="${href('/pages/lookbook')}">Lookbook</a></div><div><h3>The brand</h3><a href="${href('/pages/about-undr-rated-szn')}">Our story</a><a href="${href('/pages/behind-the-scenes-dirty-rodman')}">Behind the scenes</a><a href="${href('/pages/community')}">Join the SZN</a><a href="https://www.instagram.com/undr.rated.szn/" target="_blank" rel="noopener">Instagram ↗</a></div><div><h3>Here to help</h3><a href="${href('/pages/contact')}">Contact</a><a href="${href('/pages/size-guide')}">Sizing & fit</a><a href="${href('/policies/shipping-policy')}">Shipping</a><a href="${href('/policies/refund-policy')}">Exchanges</a></div></div><a href="${href('/')}" class="footer-mark">UNDR.RATED.SZN</a><div class="footer-bottom"><span>© 2026 UNDR.RATED.SZN · Design exploration</span><span><a style="display:inline;font-size:inherit" href="${href('/policies/privacy-policy')}">Privacy</a> &nbsp; / &nbsp; <a style="display:inline;font-size:inherit" href="${href('/policies/terms-of-service')}">Terms</a> &nbsp; / &nbsp; <a style="display:inline;font-size:inherit" href="${href('/preview-notes')}">Preview notes</a></span></div></footer><div class="prototype-band">Design prototype · Original imagery loads from the brand’s website · No live orders or submissions. <a href="${href('/preview-notes')}">What is connected?</a></div>`;}
function newsletter(){return `<section class="newsletter"><div><span class="eyebrow">Stay close to the next chapter</span><h2>JOIN THE SZN.</h2></div><div><p>First looks. Future releases. A closer look at the people and process behind UNDR.</p><button class="btn outline" data-action="newsletter">Explore sign-up <span aria-hidden="true">↗</span></button></div></section>`;}
function productCard(p){const id=imageMode==='studio'?p.flat:p.lead;return `<article class="product-card"><a class="media-link" href="${href('/products/'+p.handle)}" aria-label="View ${esc(p.name)} in ${p.color}">${media(id,imageMode==='studio'?'packshot':'')}<span class="sr-only">${esc(p.name)}</span></a><div class="product-info"><div><h3><a href="${href('/products/'+p.handle)}">${esc(p.name)}</a></h3><p><i class="small-chip ${p.id}" aria-hidden="true"></i>${p.color} ${p.id==='cream'?' / Deluxe':' / Original'}</p></div>${price(p)}</div></article>`;}
function decorateCards(){document.querySelectorAll('.product-card .media').forEach((m,i)=>{m.insertAdjacentHTML('beforeend',`<span class="card-label">${m.dataset.mediaId.startsWith('cream')?'CREAM / DELUXE':'BLACK / ORIGINAL'}</span><span class="card-arrow" aria-hidden="true">↗</span>`);});}
function intro(kicker,title,body=''){return `<section class="page-intro"><span class="eyebrow red">${kicker}</span><div class="intro-row"><h1>${title}</h1>${body?`<p>${body}</p>`:''}</div></section>`;}
function home(){return `<section class="hero"><div class="hero-visual">${media('black-portrait','',true)}${media('cream-hood')}<span class="photo-tag">01 / BLACK<br>DIRTY RODMAN</span><span class="photo-tag right">02 / CREAM<br>DELUXE EDITION</span></div><div class="hero-content"><span class="eyebrow red">THE DIRTY RODMAN COLLECTION</span><h1>ONE<br> LAST<br><em>DANCE.</em></h1><p>Two expressions. One unmistakable graphic.<br>Find the one that feels like you.</p><div class="button-row"><a class="btn red-btn" href="${href('/collections/all')}">Shop the collection <span aria-hidden="true">↗</span></a></div><a class="link" href="${href('/pages/behind-the-scenes-dirty-rodman')}">Inside the campaign <span aria-hidden="true">↗</span></a><p class="hero-meta">UNDR.RATED.SZN &nbsp; / &nbsp; REMAIN AUTHENTIC.</p></div></section><div class="principle-strip"><span class="display">UNCOMFORTABLE NIGHTS.<br>UNMISTAKABLY YOU.</span><span class="micro muted">THE CLOTHES MAKE A STATEMENT.<br>YOU MAKE THEM YOURS.</span></div><section class="space"><div class="section-heading"><div><span class="eyebrow red">THE COLLECTION / 01—02</span><h2>CHOOSE YOUR SIDE.</h2></div><div class="toggle" aria-label="Product photograph style"><button data-action="image-mode" data-mode="worn" class="${imageMode==='worn'?'selected':''}" aria-pressed="${imageMode==='worn'}">On body</button><button data-action="image-mode" data-mode="studio" class="${imageMode==='studio'?'selected':''}" aria-pressed="${imageMode==='studio'}">Product</button></div></div><div class="product-grid">${D.products.map(productCard).join('')}</div></section><section class="campaign-panel">${media('cream-back-campaign')}<div class="campaign-message"><span class="eyebrow">MORE THAN THE FRONT.</span><h2>ART YOU<br>LIVE IN.</h2><p>The graphic starts the conversation.<br>The message stays with you.</p><a class="link" href="${href('/products/deluxe-dirty-rodamn')}">Explore the Cream Deluxe <span aria-hidden="true">↗</span></a></div>${media('black-seated')}</section><section class="space story-section"><a class="media-link" href="${href('/pages/about-undr-rated-szn')}">${media('brand-riders')}</a><div class="body-copy"><span class="eyebrow red">THE STORY BEHIND THE LETTERS</span><h2>BUILT THROUGH<br>THE NIGHTS.</h2><p>U.N.D.R. stands for Uncomfortable Nights Develop Resilience. A name for the work, the growing pains, and the decision to keep creating.</p><a class="link" href="${href('/pages/about-undr-rated-szn')}">Meet UNDR.RATED.SZN <span aria-hidden="true">↗</span></a><p class="micro muted" style="font-size:9px">ARCHIVE IMAGE / PREVIOUS BRAND PIECES</p></div></section><section class="space section-rule"><div class="section-heading"><div><span class="eyebrow red">IN FRONT OF THE LENS</span><h2>YOUR WAY TO WEAR IT.</h2></div><a class="link" href="${href('/pages/lookbook')}">Open lookbook <span aria-hidden="true">↗</span></a></div><div class="mini-grid">${['cream-full-look','black-full-look','bts-pair','cream-side'].map((id,i)=>`<figure><a class="media-link" href="${href('/pages/lookbook')}">${media(id)}</a><figcaption>FRAME ${String(i+1).padStart(2,'0')} / DIRTY RODMAN</figcaption></figure>`).join('')}</div></section>${newsletter()}`;}
function shop(){const products=D.products.filter(p=>shopFilter==='all'||p.id===shopFilter);return intro('THE DIRTY RODMAN COLLECTION','MAKE IT YOURS.','A focused collection. Pick your color, see the details, and find your fit.')+`<div class="collection-tools"><div class="filter-list" aria-label="Filter products by color">${[['all','All pieces'],['black','Black'],['cream','Cream']].map(([v,t])=>`<button data-action="filter" data-filter="${v}" aria-pressed="${shopFilter===v}" class="${shopFilter===v?'selected':''}">${t}</button>`).join('')}</div><span class="micro muted">${products.length} ${products.length===1?'PIECE':'PIECES'} / USD</span></div><section class="shop-body"><div class="product-grid">${products.map(productCard).join('')}</div><p class="shop-note">Design preview · Prices captured October 14, 2026. Confirm current sizes, availability, and fulfillment on the live store.</p></section>${newsletter()}`;}
function sizeContent(p){return `<h3>Find the fit that feels right.</h3><p>${p?.id==='black'?'The live black hoodie description specifies an oversized fit.':'Fit can differ between garments. Confirm the measurements for your chosen hoodie before ordering.'}</p><p>A verified garment measurement chart and model-size details were not available in the retrieved product content. This preview deliberately does not invent chest widths, lengths, model heights, or size recommendations.</p><div class="notice">Before launch: add measured chest width, body length and sleeve length for each size, with inches/centimeters and a clear measurement diagram.</div><a class="btn wide" href="${href('/pages/contact')}" data-close>Ask a sizing question ↗</a>`;}
function accordion(title,body,open=false){return `<details class="accordion" ${open?'open':''}><summary>${title}</summary><div class="answer">${body}</div></details>`;}
function pdp(p){const current=galleryIndexes[p.id]||0;const id=p.images[current];return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="${href('/')}">HOME</a><span>/</span><a href="${href('/collections/all')}">THE COLLECTION</a><span>/</span><span>${p.color.toUpperCase()}</span></nav><section class="pdp"><div class="pdp-gallery"><button class="gallery-main media-link" data-action="zoom" data-asset="${id}" aria-label="Enlarge product photograph">${media(id,'',true)}<span class="zoom-hint">View full image +</span></button><div class="thumbnails" aria-label="Product photographs">${p.images.map((id,i)=>`<button class="${i===current?'selected':''}" data-action="gallery" data-product="${p.id}" data-index="${i}" aria-pressed="${i===current}" aria-label="View photograph ${i+1}"><img src="${esc(sourceURL(A[id],480))}" alt="${esc(A[id].alt)}" width="70" height="89" loading="lazy"></button>`).join('')}</div><p class="media-caption">${String(current+1).padStart(2,'0')} / ${String(p.images.length).padStart(2,'0')} &nbsp; ORIGINAL BRAND PHOTOGRAPHY</p></div><div class="pdp-info"><span class="eyebrow red">DIRTY RODMAN / ${p.id==='cream'?'DELUXE':'ORIGINAL'}</span><h1>${p.id==='cream'?'DELUXE DIRTY<br>RODMAN.':'DIRTY RODMAN<br>HOODIE.'}</h1>${price(p)}<p class="pdp-description">${p.description}</p><span class="micro">COLOR / ${p.color}</span><div class="color-links">${D.products.map(q=>`<a href="${href('/products/'+q.handle)}" class="${q.id===p.id?'selected':''}" ${q.id===p.id?'aria-current="page"':''}><i class="small-chip ${q.id}" aria-hidden="true"></i>${q.color}</a>`).join('')}</div><div class="size-heading"><span>SELECT SIZE</span><button data-action="size" data-product="${p.id}">Sizing & fit ↗</button></div><fieldset class="sizes"><legend>Select a size for ${p.name}</legend>${p.sizes.map(s=>`<label><input type="radio" name="size-${p.id}" value="${s}" data-size-product="${p.id}" ${selectedSizes[p.id]===s?'checked':''}><span>${s}</span></label>`).join('')}</fieldset><p class="form-error" id="size-error" role="status"></p><button class="btn red-btn wide" data-action="add" data-product="${p.id}">Add to preview bag <span aria-hidden="true">↗</span></button><p class="pdp-fineprint">Interactive design preview. Sizes shown are not live inventory.<br>All sales are final under the current policy; eligible size exchanges are conditional. <a href="${href('/policies/refund-policy')}">Read the policy.</a></p><div class="fact-strip">${p.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>${accordion('The details',p.facts.join(' · ')+'.')}${accordion('Sizing & fit',`Verified garment measurements must be added before launch. <a href="${href('/pages/size-guide')}">See the sizing guide.</a>`)}${accordion('Shipping & exchanges',`The current shipping page lists approximately 2–5 business days for processing, not delivery. The owner must confirm fulfillment timing and the collection’s release status. <a href="${href('/policies/shipping-policy')}">Shipping details.</a>`)}<p class="pdp-fineprint"><a href="${p.source}" target="_blank" rel="noopener">View this item on the live store ↗</a></p></div></section><section class="space section-rule"><div class="section-heading"><div><span class="eyebrow red">ANOTHER EXPRESSION</span><h2>THE OTHER SIDE.</h2></div><a class="link" href="${href('/collections/all')}">View collection ↗</a></div><div class="product-grid">${D.products.filter(q=>q.id!==p.id).map(productCard).join('')}<a class="media-link" href="${href('/pages/behind-the-scenes-dirty-rodman')}">${media('bts-pair')}</a></div></section><div class="sticky-buy"><p>${money(p.price)}<br><small data-mobile-size>${selectedSizes[p.id]?'Size '+selectedSizes[p.id]:'Choose your size'}</small></p><button class="btn red-btn" data-action="add" data-product="${p.id}">Add to preview bag ↗</button></div>`;}
function campaign(){return `<section class="editorial-hero"><div class="editorial-text"><span class="eyebrow red">THE CAMPAIGN / DIRTY RODMAN</span><h1>BEHIND<br>THE LAST<br>DANCE.</h1><p>The frames between the final frames. A closer look at the clothes, the people, and the work behind the campaign.</p><a class="btn red-btn" href="${href('/collections/all')}">Shop the collection ↗</a><p class="micro muted">PHOTOGRAPHY CREDIT ON THE LIVE PAGE: DMOSE<br>SHOOT DATE: SEPTEMBER 27, 2026</p></div>${media('bts-pair','',true)}</section><section class="space"><div class="section-heading"><div><span class="eyebrow red">ON SET</span><h2>BEFORE THE FRAME.</h2></div><p>Studio details and campaign photographs, without losing sight of the pieces.</p></div><div class="product-grid"><figure>${media('bts-black')}<figcaption class="media-caption">BLACK / ORIGINAL</figcaption></figure><figure>${media('bts-studio')}<figcaption class="media-caption">CREAM / DELUXE</figcaption></figure></div></section><section class="campaign-panel">${media('cream-back-detail')}<div class="campaign-message"><span class="eyebrow">FRONT. BACK. EVERY ANGLE.</span><h2>NOTHING<br>TO HIDE.</h2><p>See the full collection of product photographs and campaign frames.</p><a class="link" href="${href('/pages/lookbook')}">Open the contact sheet ↗</a></div>${media('bts-campaign')}</section><section class="space"><div class="section-heading"><div><span class="eyebrow red">TAKE IT OFF THE SET</span><h2>MAKE THE LOOK YOURS.</h2></div></div><div class="product-grid">${D.products.map(productCard).join('')}</div></section>${newsletter()}`;}
function story(){return `<section class="editorial-hero">${media('brand-riders','',true)}<div class="editorial-text"><span class="eyebrow red">THE BRAND / UNDR.RATED.SZN</span><h1>BUILT<br>THROUGH<br>THE NIGHTS.</h1><p>Uncomfortable Nights Develop Resilience.<br>A message to carry. A reason to keep creating.</p><a class="link" href="${href('/collections/all')}">Wear the message ↗</a><p class="micro muted">ARCHIVE PHOTOGRAPHY / PREVIOUS BRAND PIECES</p></div></section><article class="story-writing"><div class="chapter-label"><span class="micro red">01 / HOW IT BEGAN</span><span class="micro muted">EST. 2020</span></div><h2 class="display">PASSION STARTS IT.<br>DISCIPLINE BUILDS IT.</h2><p>The brand’s published story begins in 2020: hands-on making, direct connections with supporters, and the pull of creating something from the ground up.</p><p>That story also describes the other side of building a brand: learning structure, accepting responsibility, and finding consistency without losing creative energy.</p><p>This is the meaning at the center of U.N.D.R. Not a perfect beginning. A commitment to growth.</p><a class="link" href="${href('/pages/community')}">Be part of the next chapter ↗</a></article><section class="campaign-panel">${media('film-interview')}<div class="campaign-message"><span class="eyebrow">FROM THE BRAND ARCHIVE</span><h2>THE PEOPLE.<br>THE PROCESS.</h2><p>Original film stills from the existing brand site. Complete films remain on the live site until their source media is connected.</p><a class="link" href="https://undrszn.com/" target="_blank" rel="noopener">Visit the original film context ↗</a></div>${media('film-gallery')}</section>${newsletter()}`;}
function lookbook(){const selected=D.assets.filter(a=>archiveFilter==='all'||(archiveFilter==='photos'?a.kind!=='video_poster':a.kind==='video_poster'));return intro('THE VISUAL ARCHIVE','EVERY FRAME.','Product views, campaign portraits, studio moments, and the existing film stills. All original UNDR imagery.')+`<div class="collection-tools"><div class="filter-list">${[['all','All media'],['photos','Photography'],['films','Film stills']].map(([v,t])=>`<button data-action="archive-filter" data-filter="${v}" class="${archiveFilter===v?'selected':''}" aria-pressed="${archiveFilter===v}">${t}</button>`).join('')}</div><span class="micro muted">${selected.length} MEDIA REFERENCES</span></div><section class="lookbook">${selected.map((a,i)=>`<figure><button class="media-link" data-action="zoom" data-asset="${a.id}" aria-label="Enlarge ${esc(a.alt)}">${media(a.id,['film-car','film-arrival'].includes(a.id)?'tiny-poster':'')}</button><figcaption><span>${String(i+1).padStart(2,'0')} / ${a.kind.replace('_',' ')}</span><a href="${a.source_page}" target="_blank" rel="noopener">Original context ↗</a></figcaption></figure>`).join('')}</section><div class="shop-body"><p class="notice">Film stills are not playable videos. Three image references could not be visually verified during the audit, and the two small film thumbnails are not hero-ready. The asset manifest records these limitations.</p></div>`;}
const roles=[{slug:'brand-ambassador',title:'Brand ambassador',text:'Represent the brand through a genuine connection to its message, your community, and the clothes.',extra:'Tell us where and how you would represent UNDR.'},{slug:'model',title:'Model',text:'Bring personality, confidence, and your own way of wearing the collection to future campaigns.',extra:'Share a portfolio or a small set of recent photographs via a link.'},{slug:'sales-representative',title:'Sales representative',text:'Help introduce the collection through direct conversations and relationships.',extra:'Tell us about your sales experience and the communities you reach.'},{slug:'content-creator',title:'Content creator',text:'Give the brand a fresh perspective through original photographs, films, styling, or storytelling.',extra:'Share a portfolio link and one idea you would bring to the brand.'}];
function community(){return intro('THE PEOPLE BEHIND THE SZN','BRING YOUR<br>OWN ENERGY.','A place for the people who connect with the message and want to help shape what comes next.')+`<section class="role-list">${roles.map((r,i)=>`<article class="role"><span class="micro red">0${i+1}</span><h2>${r.title}</h2><p>${r.text}</p><a class="link" href="${href('/pages/'+r.slug+'-application')}">Explore role ↗</a></article>`).join('')}</section><section class="space section-rule story-section">${media('bts-pair')}<div class="body-copy"><span class="eyebrow red">WEAR IT YOUR WAY</span><h2>THE NEXT FRAME<br>COULD BE YOURS.</h2><p>Show the brand your perspective. Community photographs should only be featured after permission and review.</p><a class="link" href="${href('/pages/content-creator-application')}">Share your perspective ↗</a></div></section>`;}
function field(label,name,type='text',full=false,required=true){return `<div class="field ${full?'full':''}"><label for="${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" ${required?'required':''} maxlength="3000"></textarea>`:`<input id="${name}" name="${name}" type="${type}" ${required?'required':''} maxlength="300" ${type==='email'?'autocomplete="email"':name==='name'?'autocomplete="name"':''}>`}</div>`;}
function application(role){return intro('JOIN THE SZN / APPLICATION',role.title+'.','Your perspective matters more than a perfect pitch.')+`<section class="form-layout"><div class="form-sidebar"><span class="eyebrow red">WHAT TO SHARE</span><h2>MAKE YOUR<br>INTRODUCTION.</h2><p>${role.text}</p><p>${role.extra}</p><p class="micro muted">THIS IS A FORM DESIGN PREVIEW.<br>APPLICATIONS ARE NOT SENT OR STORED.</p>${media('black-seated')}</div><form class="form-fields" data-preview-form="application">${field('Full name','name')}${field('Email address','email','email')}${field('City / region','city')}${field('Instagram or portfolio link','portfolio','url',false,false)}${field('What would you bring to UNDR?','message','textarea',true)}<div class="field full"><label class="check-label"><input type="checkbox" required name="consent">I understand this prototype will not send an application or store my personal information.</label></div><p class="form-disclosure">For production: connect the application to an approved destination and add role-specific privacy and consent language.</p><button class="btn red-btn" type="submit">Review application preview ↗</button><div class="form-status" role="status"></div></form></section>`;}
function contact(){return intro('CUSTOMER CARE','LET’S TALK.','Questions about a piece, sizing, an order, or the brand? Start here.')+`<section class="form-layout"><div class="form-sidebar"><span class="eyebrow red">A DIRECT LINE</span><h2>REAL QUESTIONS.<br>REAL PEOPLE.</h2><p>For an existing order, include the order number so the brand can find the details.</p><p><a class="link" href="mailto:${D.public_contact_email}">${D.public_contact_email} ↗</a><br><small class="muted">Email published in the brand’s current privacy policy.</small></p><p><a href="${href('/policies/shipping-policy')}" class="link">Shipping information ↗</a><br><a href="${href('/policies/refund-policy')}" class="link">Size exchanges ↗</a></p></div><form class="form-fields" data-preview-form="contact">${field('Your name','name')}${field('Email address','email','email')}<div class="field full"><label for="topic">What is this about? *</label><select id="topic" name="topic" required><option value="">Select a topic</option><option>Sizing &amp; product details</option><option>An existing order</option><option>Shipping</option><option>Size exchange</option><option>Collaboration</option><option>Something else</option></select></div>${field('Order number (when relevant)','order','text',true,false)}${field('Your message','message','textarea',true)}<p class="form-disclosure">Preview only. Submitting checks the form; it does not email the brand or save this information. Use the published email link for an actual inquiry.</p><button class="btn red-btn" type="submit">Review message preview ↗</button><div class="form-status" role="status"></div></form></section>`;}
const policyInfo={
 'shipping-policy':{title:'Shipping',sections:[['Processing and delivery','The current page gives approximately 2–5 business days for processing. Delivery time starts separately once a carrier receives the parcel.'],['Preorders','Any preorder or made-to-order schedule must be stated on the product page. The collection’s release and fulfillment status still needs owner confirmation.'],['Tracking and address questions','Use your order’s shipping notification for tracking. Contact the brand with the order number when help is needed.']],note:'Layout preview, not a replacement policy. Confirm the fulfillment estimate and remove the drafting note currently published on the live shipping page.'},
 'refund-policy':{title:'Exchanges',sections:[['Before you buy','The current policy states that sales are final, while certain items can qualify for a size exchange. Do not describe this as free returns.'],['Request window','The published request window is seven days after delivery. Eligibility depends on condition, packaging and size availability.'],['Incorrect or damaged item','Contact the brand promptly with your order number and photographs.']],note:'Layout preview, not a replacement policy. The owner must clarify how the general final-sale wording differs from items explicitly excluded from exchange.'},
 'privacy-policy':{title:'Privacy',sections:[['Your information','The live policy describes how the brand and its service providers handle customer information.'],['Choices and requests','Use the current policy for the full explanation of privacy choices, contact methods, and applicable rights.']],note:'The full current policy remains on the live store. This design preview does not recreate or modify legal terms. No application or newsletter information is stored by this prototype.'},
 'terms-of-service':{title:'Terms of service',sections:[['Shopping with UNDR','The published terms cover orders, availability, product representation, payment and other store conditions.'],['The authoritative version','Review the full current terms on the live store before making a purchase.']],note:'Typography and navigation preview only. Full approved terms must be rendered from the existing Shopify policy object in production.'},
 'contact-information':{title:'Contact information',sections:[['Email','The brand’s current privacy policy publishes '+D.public_contact_email+'. Confirm that this is the intended customer-service address before making it the storewide support contact.'],['Help with an order','Include your name and order number in a private support message. Do not send card details.']],note:'The separate live contact-information page still contains placeholder text. This preview uses the email published elsewhere by the brand, not an invented support address.'}
};
function policy(slug){const x=policyInfo[slug];return intro('CUSTOMER CARE / INFORMATION',x.title+'.')+`<section class="legal-layout"><nav class="legal-nav" aria-label="Customer care policies">${Object.entries(policyInfo).map(([s,p])=>`<a href="${href('/policies/'+s)}" class="${s===slug?'active':''}">${p.title}</a>`).join('')}<a href="${href('/pages/contact')}">Send an inquiry</a></nav><article class="legal-body"><div class="notice">${x.note}</div>${x.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<a class="btn" href="https://undrszn.com/policies/${slug}" target="_blank" rel="noopener">Read the full current policy ↗</a></article></section>`;}
function sizing(){return intro('CUSTOMER CARE / SIZING','GET THE FIT RIGHT.','Clear measurements belong beside every garment—not hidden behind a guess.')+`<section class="legal-layout"><nav class="legal-nav"><a href="${href('/products/dirty-rodman-hoodie')}">Black hoodie</a><a href="${href('/products/deluxe-dirty-rodamn')}">Cream Deluxe</a><a href="${href('/pages/contact')}">Ask a sizing question</a></nav><div class="legal-body">${sizeContent()}<h2>What the finished guide will include</h2><p>Measured garment width, length and sleeve length; a diagram of where to measure; a unit switch; and verified model height and worn size next to the relevant photograph.</p><p>No customer measurements are collected by this preview.</p></div></section>`;}
function searchPage(query=''){const q=query.toLowerCase().trim();const results=D.products.filter(p=>(p.name+' '+p.color+' '+p.facts.join(' ')).toLowerCase().includes(q));return intro('FIND YOUR PIECE','SEARCH UNDR.')+`<form class="search-box" id="search-form"><label><span class="sr-only">Search products</span><input type="search" name="q" value="${esc(query)}" placeholder="Try ‘cream’ or ‘hoodie’" maxlength="120"></label><button class="btn" type="submit">Search ↗</button></form><p class="results-label" role="status">${q?`${results.length} results for “${esc(query)}”`:'Explore both pieces in the current collection.'}</p><section class="shop-body">${results.length?`<div class="product-grid in-search">${results.map(productCard).join('')}</div>`:`<div class="empty-state"><h2>NOT HERE. YET.</h2><p>No products match that search. Try a color, the product name, or browse the full collection.</p><a class="btn red-btn" href="${href('/collections/all')}">View all pieces ↗</a></div>`}</section>`;}
function cartRows(){return cart.map((l,i)=>{const p=P[l.product];return `<article class="cart-row"><a href="${href('/products/'+p.handle)}" data-close>${media(p.lead)}</a><div><h3><a href="${href('/products/'+p.handle)}" data-close>${esc(p.name)}</a></h3><p>${p.color} / ${esc(l.size)}</p><div class="qty" aria-label="Quantity"><button data-action="quantity" data-index="${i}" data-change="-1" aria-label="Decrease quantity for ${esc(p.name)} ${esc(l.size)}">−</button><span>${l.qty}</span><button data-action="quantity" data-index="${i}" data-change="1" ${l.qty>=9?'disabled':''} aria-label="Increase quantity for ${esc(p.name)} ${esc(l.size)}">+</button></div><button class="remove" data-action="remove" data-index="${i}">Remove</button></div><span class="prices">${money(p.price*l.qty)}</span></article>`;}).join('');}
function cartSummary(){return `<aside class="cart-summary"><h2>Your preview bag</h2><div class="total-row"><span>Item subtotal</span><strong>${money(total())}</strong></div><p>Shipping, tax and actual stock are not calculated in this prototype. Your bag is local to this browser and does not transfer to the live store.</p><button class="btn red-btn wide" data-action="checkout">Preview checkout handoff ↗</button><a class="link" href="${href('/cart')}" data-close>View full bag ↗</a></aside>`;}
function cartEmpty(){return `<div class="empty-state"><span class="eyebrow red">A FRESH START</span><h2>MAKE ROOM<br>FOR UNDR.</h2><p>Your preview bag is empty.</p><a class="btn red-btn" href="${href('/collections/all')}" data-close>Explore the collection ↗</a></div>`;}
function cartPage(){return intro('THE COLLECTION / YOUR SELECTION','YOUR BAG.',`${count()} preview ${count()===1?'piece':'pieces'}. No order has been placed.`)+(cart.length?`<section class="cart-layout"><div>${cartRows()}</div>${cartSummary()}</section>`:cartEmpty());}
function account(){return intro('CUSTOMER ACCOUNT','BACK FOR MORE?','Order history and sign-in stay with the brand’s secure Shopify account experience.')+`<section class="story-writing"><h2 class="display">YOUR ORDERS.<br>YOUR ACCOUNT.</h2><p>This design prototype does not collect login credentials or access customer orders.</p><a class="btn red-btn" href="https://undrszn.com/customer_authentication/redirect?locale=en&region_country=US" target="_blank" rel="noopener">Open the live customer account ↗</a><p class="muted" style="font-size:12px">The authenticated account flow was not audited. The production design must respect the capabilities of the store’s Shopify account configuration.</p></section>`;}
function help(){return intro('CUSTOMER CARE','A LITTLE CLARITY.')+`<section class="story-writing">${accordion('How do I choose a size?',`<a href="${href('/pages/size-guide')}">Visit sizing & fit.</a> Verified garment measurements still need to be supplied.`)}${accordion('When will my order ship?',`<a href="${href('/policies/shipping-policy')}">Read shipping information.</a> Processing and delivery are separate.`)}${accordion('Can I exchange my size?',`<a href="${href('/policies/refund-policy')}">Read exchange conditions.</a> Do not assume an exchange is guaranteed.`)}${accordion('How can I reach the brand?',`<a href="${href('/pages/contact')}">Open customer care.</a>`)}${accordion('Can I apply to work with the brand?',`<a href="${href('/pages/community')}">Explore the four existing role categories.</a> Application submission in this file is a preview only.`)}</section>`;}
function notes(){const pageLinks=['/','/collections/all','/products/dirty-rodman-hoodie','/products/deluxe-dirty-rodamn','/pages/behind-the-scenes-dirty-rodman','/pages/lookbook','/pages/about-undr-rated-szn','/pages/community',...roles.map(r=>'/pages/'+r.slug+'-application'),'/pages/contact','/pages/size-guide','/pages/help',...Object.keys(policyInfo).map(s=>'/policies/'+s),'/search','/cart','/account','/404'];return intro('DESIGN REVIEW / OCTOBER 14, 2026','THE PREVIEW.','A complete visual direction with working local interactions, using the brand’s original published media.')+`<article class="qa-notes"><h2>What works here</h2><p>Responsive page layouts, navigation, both product pages, photograph switching, image enlargement, collection filters, photograph-mode switching, archive filtering, product search, size selection, a persistent local bag, quantity changes, removal, accordions, mobile navigation and honest form-validation previews.</p><h2>What is not connected</h2><p>This is not a production theme or a live store. Inventory, actual variants, payment, shipping calculation, order creation, account login, application delivery, newsletter enrollment, consent collection and email delivery are not integrated. Policy pages preview the presentation and link to the authoritative live text.</p><h2>Media and visual review</h2><p>The manifest records 23 unique media references: 19 photographs/product images and four video-poster references. Three references were discovered but not visually verified. Film playback is deliberately not fabricated. Media loads from the original site and requires internet access. Browser-compatible export of the HEIC source and full-resolution video sources remain production tasks.</p><p>The wordmark is a typeset concept lockup, not a recovered original logo file. Photographs and product artwork are not generated or redrawn. Product facts are a dated snapshot, not a stock feed.</p><h2>Commercial corrections before launch</h2><p>Resolve the cream hoodie’s 400/420 GSM conflict. Reconcile XXS and 2XS without deleting real variants. Confirm whether October 30 is a release date, a preorder date, or stale campaign copy. Remove published drafting notes and the support-email placeholder. Confirm the final-sale/size-exchange distinction. Supply measured size charts. Confirm image, model, artwork and film permissions with the brand.</p><h2>Every review destination</h2><div class="notes-links">${pageLinks.map(p=>`<a href="${href(p)}">${p==='/'?'Home':p.replace('/pages/','').replace('/policies/','').replace('/products/','').replaceAll('-',' ')}</a>`).join('')}</div><h2>Asset inventory</h2><table class="qa-table"><thead><tr><th>Asset</th><th>Type</th><th>Review status</th></tr></thead><tbody>${D.assets.map(a=>`<tr><td><a href="${a.original_url}" target="_blank" rel="noopener">${a.id} ↗</a></td><td>${a.kind.replace('_',' ')}</td><td>${a.inspection}${a.notes?'<br>'+esc(a.notes):''}</td></tr>`).join('')}</tbody></table><h2>Production route</h2><p>Implement the approved direction as a custom Shopify section-based theme. Preserve product handles, customer records, orders, analytics and the existing checkout. This hash-routed file is a design review artifact, not the recommended production architecture.</p></article>`;}
function notFound(){return intro('404 / OFF THE RACK','WRONG TURN.')+`<section class="empty-state"><p>This page is not part of the preview. The collection is right here.</p><a class="btn red-btn" href="${href('/collections/all')}">Back to the collection ↗</a></section>`;}
function render(keepScroll=false){const previousScroll=window.scrollY;const raw=location.hash.startsWith('#/')?location.hash.slice(1):'/';let u;try{u=new URL(raw,'https://preview.local');}catch{u=new URL('https://preview.local/');}activePath=u.pathname;let content,title='UNDR.RATED.SZN';const product=D.products.find(p=>activePath==='/products/'+p.handle);const role=roles.find(r=>activePath==='/pages/'+r.slug+'-application');if(product){content=pdp(product);title=product.name;}else if(role){content=application(role);title=role.title;}else if(activePath.startsWith('/policies/')&&policyInfo[activePath.split('/').pop()]){const slug=activePath.split('/').pop();content=policy(slug);title=policyInfo[slug].title;}else{const routes={'/':[home,'Home'],'/collections/all':[shop,'The collection'],'/pages/behind-the-scenes-dirty-rodman':[campaign,'The campaign'],'/pages/about-undr-rated-szn':[story,'Our story'],'/pages/lookbook':[lookbook,'Lookbook'],'/pages/community':[community,'Join the SZN'],'/pages/contact':[contact,'Contact'],'/pages/size-guide':[sizing,'Sizing & fit'],'/pages/help':[help,'Help'],'/search':[()=>searchPage(u.searchParams.get('q')||''),'Search'],'/cart':[cartPage,'Your bag'],'/account':[account,'Your account'],'/preview-notes':[notes,'Preview notes']};const route=routes[activePath]||[notFound,'Page not found'];content=route[0]();title=route[1];}app.innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();document.title=title+' — UNDR.RATED.SZN | Design Preview';decorateCards();bindMediaErrors();if(keepScroll)window.scrollTo({top:previousScroll,behavior:'instant'});else{document.getElementById('main').focus({preventScroll:true});window.scrollTo({top:scrollMemory[raw]||0,behavior:'instant'});}}
function bindMediaErrors(){document.querySelectorAll('img').forEach(img=>{img.addEventListener('error',()=>img.closest('.media')?.classList.add('media-error'),{once:true});if(img.complete&&img.naturalWidth===0)img.closest('.media')?.classList.add('media-error');});}
function openModal(title,body,kind=''){lastFocus=document.activeElement;modal.className='dialog '+kind;modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!modal.open)modal.showModal();bindMediaErrors();}
function closeModal(){if(modal.open)modal.close();lastFocus?.focus?.({preventScroll:true});}
function showBag(){openModal('Your preview bag / '+count()+' pieces',cart.length?cartRows()+cartSummary():cartEmpty(),'drawer');}
let toastTimer;function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600);}
function updateCartView(){saveCart();if(activePath==='/cart')render(true);if(modal.open&&modal.classList.contains('drawer'))showBag();}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a?.getAttribute('href')?.startsWith('#/')){scrollMemory[location.hash.slice(1)||'/']=window.scrollY;if(modal.open)closeModal();}if(e.target.closest('[data-close]'))closeModal();const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(act==='close')closeModal();else if(act==='menu')openModal('UNDR.RATED.SZN',`<nav class="menu-links" aria-label="Mobile navigation"><a href="${href('/collections/all')}">Shop the collection ↗</a><a href="${href('/pages/behind-the-scenes-dirty-rodman')}">The campaign ↗</a><a href="${href('/pages/lookbook')}">Lookbook ↗</a><a href="${href('/pages/about-undr-rated-szn')}">Our story ↗</a><a href="${href('/pages/community')}">Join the SZN ↗</a><a href="${href('/pages/contact')}">Contact ↗</a><a href="${href('/search')}">Search ↗</a><a href="${href('/account')}">Account ↗</a></nav>`,'drawer');else if(act==='bag')showBag();else if(act==='filter'){shopFilter=b.dataset.filter;render(true);}else if(act==='image-mode'){imageMode=b.dataset.mode;render(true);}else if(act==='archive-filter'){archiveFilter=b.dataset.filter;render(true);}else if(act==='gallery'){galleryIndexes[b.dataset.product]=Number(b.dataset.index);render(true);document.querySelector(`button[data-product="${b.dataset.product}"][data-index="${b.dataset.index}"]`)?.focus({preventScroll:true});}else if(act==='size')openModal('Sizing & fit',sizeContent(P[b.dataset.product]));else if(act==='zoom'){const a=A[b.dataset.asset];openModal('THE ORIGINAL FRAME',`<figure>${media(a.id,'',true)}<figcaption>${esc(a.alt)}<br><a href="${esc(a.original_url)}" target="_blank" rel="noopener">Open original image ↗</a></figcaption></figure>`,'lightbox');}else if(act==='add'){const p=P[b.dataset.product],size=selectedSizes[p.id];if(!size){const err=document.getElementById('size-error');err.textContent='Choose a size before adding this piece.';document.querySelector('.sizes input')?.focus();return;}const line=cart.find(l=>l.product===p.id&&l.size===size);if(line&&line.qty>=9){toast('Preview quantities are limited to nine per size.');return;}if(line)line.qty++;else cart.push({product:p.id,size,qty:1});saveCart();showBag();}else if(act==='quantity'){const i=Number(b.dataset.index);if(cart[i]){cart[i].qty=Math.min(9,Math.max(0,cart[i].qty+Number(b.dataset.change)));cart=cart.filter(l=>l.qty>0);updateCartView();}}else if(act==='remove'){cart.splice(Number(b.dataset.index),1);updateCartView();}else if(act==='checkout'){openModal('Checkout / integration boundary',`<h3>Your preview item subtotal: ${money(total())}</h3><p>This is the point where the production theme hands the real Shopify cart to Shopify checkout. No payment details are requested here, and no order has been placed.</p><div class="notice">Your preview bag will not transfer. Current price, selected variants, availability, shipping and taxes must be checked on the live store.</div><a class="btn red-btn wide" href="https://undrszn.com/collections/all" target="_blank" rel="noopener">Visit the live collection ↗</a>`);}else if(act==='newsletter'){openModal('Join the SZN / form preview',`<h3>Stay close to what comes next.</h3><p>Preview the signup experience. Your email will not be sent or saved.</p><form class="form-fields" data-preview-form="newsletter">${field('Email address','newsletter-email','email',true)}<div class="field full"><label class="check-label"><input type="checkbox" name="consent" required>I understand this is a design preview, not a live subscription.</label></div><button type="submit" class="btn red-btn">Review signup preview ↗</button><div class="form-status" role="status"></div></form>`);}});
document.addEventListener('change',e=>{if(e.target.matches('[data-size-product]')){selectedSizes[e.target.dataset.sizeProduct]=e.target.value;const err=document.getElementById('size-error');if(err)err.textContent='';const label=document.querySelector('[data-mobile-size]');if(label)label.textContent='Size '+e.target.value;}});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();const q=new FormData(e.target).get('q')||'';location.hash='/search?q='+encodeURIComponent(q);if(activePath==='/search')render();}else if(e.target.matches('[data-preview-form]')){e.preventDefault();const status=e.target.querySelector('.form-status');status.textContent='Preview checked. Nothing was sent, and no personal information was stored.';status.setAttribute('tabindex','-1');status.focus();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();render();});
render();
